handler <- handler_slowdown(duration = 0, enable = TRUE)
total <- with_progress({
  p <- progressor(steps = 4, on_exit = FALSE)
  s <- 0
  for (i in 1:4) {
    p()
    s <- s + i
  }
  s
}, handlers = handler, enable = TRUE, interval = 0, delay_terminal = FALSE, delay_stdout = FALSE, delay_conditions = character())
cat("handler_slowdown with duration 0 returns ", total, ".\n", sep = "")
